
-- ===========================================================================
--  MEDIA SEED — 45 photographs extracted from the department documents
--  Run after schema_media.sql. Safe to re-run.
-- ===========================================================================

ON CONFLICT (filename) DO NOTHING;

-- Link photos to the events they document, by matching keywords in the title.
UPDATE media m SET event_id = e.id
FROM events e
WHERE m.event_id IS NULL AND (
     (m.media_key = 'blind-coding-competition'  AND e.title ILIKE '%Blind Coding%')
  OR (m.media_key = 'devops-workshop-iconnect'  AND e.title ILIKE '%DevOps%')
  OR (m.media_key = 'alumni-mystory-board'      AND e.title ILIKE '%MyStory%')
  OR (m.media_key = 'thought-leader-jaokar'     AND e.title ILIKE '%Thought Leader%')
  OR (m.media_key = 'session-tashkent-university' AND e.title ILIKE '%Global Research%')
  OR (m.media_key = 'project-competition'       AND e.title ILIKE '%Project Competition%')
  OR (m.media_key = 'iks-heritage-activity'     AND e.title ILIKE '%Indian Knowledge%')
  OR (m.media_key = 'parent-teacher-meeting'    AND e.title ILIKE '%Parent-Teacher%')
);

-- Link photos to laboratories.
UPDATE media m SET lab_id = l.id
FROM labs l
WHERE m.lab_id IS NULL
  AND m.media_key = 'laboratory-specification'
  AND l.name = CASE m.sort_order WHEN 1 THEN 'Computer Vision Laboratory'
                                 ELSE 'Data Science Laboratory' END;

-- Link photos to the achievements they document.
UPDATE media m SET achievement_id = fa.id
FROM faculty_achievements fa
WHERE m.achievement_id IS NULL AND (
     (m.media_key = 'micromouse-iit-guwahati' AND fa.title ILIKE '%Micromouse%')
  OR (m.media_key = 'techdeviathon-2026'      AND fa.title ILIKE '%TechDeviathon%')
  OR (m.media_key = 'iinnoyudh-2k25'          AND fa.title ILIKE '%IInnoYudh%')
  OR (m.media_key = 'hackwave-2'              AND fa.title ILIKE '%Hackwave%')
  OR (m.media_key = 'coe-hitspectra-taiwan'   AND fa.title ILIKE '%Centre of Excellence%')
  OR (m.media_key = 'incubation-centre-taiwan' AND fa.title ILIKE '%Innovation Incubation%')
  OR (m.media_key = 'internship-taiwan'       AND fa.title ILIKE '%Chung Cheng%')
  OR (m.media_key = 'internship-iit-bhu'      AND fa.title ILIKE '%IIT (BHU)%')
  OR (m.media_key = 'sap-certification'       AND fa.title ILIKE '%SAP%')
  OR (m.media_key = 'goethe-a1-german'        AND fa.title ILIKE '%Goethe%')
  OR (m.media_key = 'prenaya-softtech'        AND fa.title ILIKE '%Prenaya%')
);

SELECT section, count(*) AS photos,
       count(event_id) AS linked_events,
       count(lab_id) AS linked_labs,
       count(achievement_id) AS linked_achievements
FROM media GROUP BY section ORDER BY section;
